      { "label": "Sunshine Coast flooding and stormwater management guidelines", "href": "https://www.sunshinecoast.qld.gov.au/development/development-tools-and-guidelines/infrastructure-guidelines-and-standards/flooding-and-stormwater-management-guidelines" },
      { "label": "Sunshine Coast operational work applications", "href": "https://www.sunshinecoast.qld.gov.au/development/development-applications/operational-work" }
